function Export-WsmSourceStageResult {
    param([string]$ManifestPath,[string]$ExpectedHash,[string]$SourceStateDirectory,[ValidateSet('Export','FinalDelta')][string]$Stage,[string]$Path)
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $p.Manifest.Source.Fingerprint;if($Stage -eq 'FinalDelta' -and -not $p.Manifest.Final){throw 'FinalDelta result requires frozen final generation.'}
    $root=Join-Path ([IO.Path]::GetFullPath($SourceStateDirectory)) ('result-'+$p.Manifest.PairId);if(-not [IO.Directory]::Exists($root)){[void][IO.Directory]::CreateDirectory($root);Protect-WsmDirectory $root};Assert-WsmNoReparse $root
    Invoke-WsmLocked $root {$statePath=Join-Path $root 'state.json';if([IO.File]::Exists($statePath)){$s=Read-WsmJson $statePath;if($s.SourceFingerprint -cne $p.Manifest.Source.Fingerprint -or $s.PlanHash -ine $p.Manifest.PlanHash){throw 'Source result state belongs to another identity/approval.'}}else{$s=[pscustomobject]@{SourceFingerprint=$p.Manifest.Source.Fingerprint;PlanHash=$p.Manifest.PlanHash;RunId=[Guid]::NewGuid().ToString();Sequence=0}};$s.Sequence++
        $r=[pscustomobject]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='StageResult';BatchId=$p.Manifest.BatchId;PairId=$p.Manifest.PairId;SourceHostId=$p.Plan.Source.HostId;TargetHostId=$p.Plan.Target.HostId;TargetFingerprint=$p.Plan.Target.Fingerprint;InventoryRevision=$p.Manifest.InventoryRevision;DecisionRevision=$p.Manifest.DecisionRevision;ApprovalId=$p.Manifest.ApprovalId;PlanHash=$p.Manifest.PlanHash;ManifestHash=$ExpectedHash;PayloadGeneration=$p.Manifest.Generation;RunId=$s.RunId;Sequence=$s.Sequence;Stage=$Stage;Status='Succeeded';ProducedUtc=(Get-WsmUtc);Mode='IsolatedPilot';ProductionVerified=$false;JournalHash=$p.Manifest.ArtifactsHash};Write-WsmJson $Path $r;Write-WsmJson $statePath $s;[pscustomobject]@{Path=[IO.Path]::GetFullPath($Path);SHA256=(Get-FileHash -LiteralPath $Path).Hash;Result=$r}
    }
}
